"""Unit G: Algorithms and coding interviews (theory, tracing and complexity; the hands-on problems live in challenges.py)."""

from __future__ import annotations

from app.services.python_practice.content.build import mcq as M, out as O


def questions() -> list[dict]:
    return [
        O("array-problems", "medium", "Trace the code. What is printed?", "a = [2, 7, 11, 15]\nbest = 0\nfor i in range(len(a) - 1):\n    best = max(best, a[i + 1] - a[i])\nprint(best)", "5", ["4", "13", "9"], "The loop computes adjacent differences: 7-2 = 5, 11-7 = 4 and 15-11 = 4. The largest is 5.", fmt="trace"),
        M("array-problems", "medium", "To rotate a list left by k positions in O(n) time, which approach is correct?", "Use k %= len(a), then a[k:] + a[:k]", ["Call a.pop(0) k times (O(n*k))", "Sort the list k times", "a.reverse() once"], "Slicing builds the rotated list in O(n); repeated pop(0) is O(n) per call. Normalise k with modulo and handle an empty list."),
        O("string-manipulation", "medium", "What is printed?", "s = 'A man, a plan'\nclean = ''.join(c.lower() for c in s if c.isalnum())\nprint(clean, clean == clean[::-1])", "amanaplan False", ["A man, a plan False", "amanaplan True", "amanaplan[::-1] False"], "isalnum drops spaces and punctuation; 'amanaplan' reversed is 'nalpanama', so it is not a palindrome."),
        M("string-manipulation", "medium", "Building a long string by `s += piece` in a loop is discouraged because:", "Strings are immutable, so each += may copy the whole string; collect pieces in a list and ''.join() them", ["+= is not allowed on strings", "It changes the string's encoding", "It always raises MemoryError"], "CPython sometimes optimises +=, but join is the portable linear-time idiom."),
        O("hash-maps", "medium", "Trace the code. What is printed?", "nums, target = [2, 7, 11, 15], 9\nseen = {}\nfor i, n in enumerate(nums):\n    if target - n in seen:\n        print(seen[target - n], i)\n        break\n    seen[n] = i", "0 1", ["1 0", "2 7", "None"], "At i=1 (n=7) the complement 2 is already in seen at index 0.", fmt="trace"),
        M("hash-maps", "easy", "What is the average time complexity of dict lookup and set membership?", "O(1)", ["O(n)", "O(log n)", "O(n log n)"], "Both use hash tables; the worst case degrades with many collisions but is rare with good hashes."),
        O("two-pointers", "medium", "Trace the code. What is printed?", "a = [1, 2, 3, 4, 6]\ni, j, t = 0, len(a) - 1, 6\nwhile i < j:\n    s = a[i] + a[j]\n    if s == t: break\n    i, j = (i + 1, j) if s < t else (i, j - 1)\nprint(i, j)", "1 3", ["0 4", "2 3", "1 4"], "1+6=7>6 moves j; 1+4=5<6 moves i; 2+4=6 matches at (1, 3).", fmt="trace"),
        M("two-pointers", "medium", "The two-pointer pair-sum technique on a sorted array runs in:", "O(n) time and O(1) extra space", ["O(n^2) time", "O(n log n) time and O(n) space", "O(log n) time"], "Each step moves one pointer inward, so total moves are at most n."),
        O("sliding-window", "medium", "Trace the code. What is printed?", "a, k = [1, 3, 2, 6, -1, 4], 3\nw = sum(a[:k]); best = w\nfor i in range(k, len(a)):\n    w += a[i] - a[i - k]\n    best = max(best, w)\nprint(best)", "11", ["12", "10", "6"], "Windows sum to 6, 11, 7, 9; the maximum is 11 (3+2+6).", fmt="trace"),
        M("sliding-window", "medium", "Why is a sliding window faster than recomputing every window's sum?", "It updates the sum by adding the entering element and removing the leaving one, giving O(n) instead of O(n*k)", ["It sorts the array first", "It uses recursion", "It only checks the first window"], "Each element enters and leaves once."),
        O("stack-queue", "medium", "What is printed?", "stack = []\nfor ch in '([]{})':\n    if ch in '([{':\n        stack.append(ch)\n    else:\n        stack.pop()\nprint(stack, len(stack) == 0)", "[] True", ["['('] False", "[] False", "IndexError"], "Every closer pops its opener, leaving an empty stack: the brackets are balanced (a full solution also checks that each closer matches the popped opener)."),
        M("stack-queue", "medium", "Which structure fits breadth-first search and why?", "A queue (collections.deque): nodes are processed in the order discovered, level by level", ["A stack, because newest first", "A set, because order is unnecessary", "A sorted list, always"], "BFS is FIFO. Use deque.popleft() for O(1); list.pop(0) is O(n)."),
        O("searching-sorting", "medium", "What is printed?", "import bisect\na = [1, 3, 3, 5]\nprint(bisect.bisect_left(a, 3), bisect.bisect_right(a, 3), bisect.bisect_left(a, 4))", "1 3 3", ["1 2 2", "1 3 2", "0 3 3"], "bisect_left gives the first position where 3 could be inserted, bisect_right the position after the last 3; 4 would go at index 3."),
        M("searching-sorting", "medium", "Python's built-in sort (Timsort) has which worst-case time complexity and stability?", "O(n log n) and it is stable", ["O(n^2) and unstable", "O(n) and stable", "O(n log n) and unstable"], "Stable means equal keys keep their original order, enabling multi-pass sorts."),
        O("binary-search", "medium", "Trace the code. What is printed?", "a, t = [1, 3, 5, 7, 9, 11], 7\nlo, hi, steps = 0, len(a) - 1, 0\nwhile lo <= hi:\n    steps += 1\n    mid = (lo + hi) // 2\n    if a[mid] == t: break\n    lo, hi = (mid + 1, hi) if a[mid] < t else (lo, mid - 1)\nprint(mid, steps)", "3 3", ["3 1", "3 2", "4 3"], "Probe 1: mid = 2, a[2] = 5 < 7 so lo = 3. Probe 2: mid = 4, a[4] = 9 > 7 so hi = 3. Probe 3: mid = 3, a[3] = 7 matches. The index is 3 after 3 steps.", fmt="trace"),
        M("binary-search", "medium", "What must be true before using binary search on a list?", "The list must be sorted by the search key", ["The list must contain unique numbers only", "The list must have even length", "The list must be a tuple"], "Binary search discards half of the range each step based on order; without sorting it gives wrong answers."),
        O("backtracking", "medium", "What is printed?", "def subsets(a):\n    res = []\n    def go(i, cur):\n        if i == len(a):\n            res.append(cur[:]); return\n        go(i + 1, cur)\n        cur.append(a[i]); go(i + 1, cur); cur.pop()\n    go(0, [])\n    return res\n\nprint(subsets([1, 2]))", "[[], [2], [1], [1, 2]]", ["[[], [1], [2], [1, 2]]", "[[1, 2], [1], [2], []]", "[[], [1], [1, 2]]"], "Each element is first excluded, then included. cur[:] copies the path before backtracking with pop()."),
        M("backtracking", "hard", "In backtracking, why copy the current path (cur[:]) before saving it?", "Otherwise every saved result is the same list object that later steps keep mutating", ["Copying makes the recursion faster", "Python forbids appending lists", "To sort the path"], "Appending cur directly stores a reference; after backtracking it ends up empty."),
        M("linked-lists", "medium", "What is the main advantage of a singly linked list over a Python list?", "O(1) insertion or removal at a known node without shifting elements", ["O(1) random access by index", "Lower memory per element", "Built-in sorting"], "Linked lists trade random access for cheap splicing; in practice Python lists are usually faster because of cache locality."),
        O("linked-lists", "medium", "What is printed?", "class N:\n    def __init__(self, v, nxt=None): self.v, self.nxt = v, nxt\n\nhead = N(1, N(2, N(3)))\nprev, cur = None, head\nwhile cur:\n    cur.nxt, prev, cur = prev, cur, cur.nxt\nout = []\nwhile prev:\n    out.append(prev.v); prev = prev.nxt\nprint(out)", "[3, 2, 1]", ["[1, 2, 3]", "[3]", "[1]"], "The loop reverses every nxt pointer in place using three names (a tuple assignment evaluates the right side first)."),
        M("trees-graphs", "medium", "Which traversal of a binary search tree visits keys in sorted order?", "In-order (left, node, right)", ["Pre-order", "Post-order", "Level-order"], "In-order on a BST yields ascending keys."),
        O("trees-graphs", "medium", "What is printed?", "from collections import deque\ng = {'a': ['b', 'c'], 'b': ['d'], 'c': ['d'], 'd': []}\nseen, q, order = {'a'}, deque(['a']), []\nwhile q:\n    n = q.popleft(); order.append(n)\n    for m in g[n]:\n        if m not in seen:\n            seen.add(m); q.append(m)\nprint(order)", "['a', 'b', 'c', 'd']", ["['a', 'b', 'd', 'c']", "['a', 'c', 'b', 'd']", "['a', 'b', 'c', 'd', 'd']"], "BFS visits level by level; the visited set stops d from being queued twice.", fmt="trace"),
        M("dynamic-programming", "medium", "What are the two hallmarks of a problem suited to dynamic programming?", "Overlapping subproblems and optimal substructure", ["Sorted input and unique keys", "Recursion depth below 1000", "Only integer inputs"], "Cache results of repeated subproblems (memoisation) or fill a table bottom-up."),
        O("dynamic-programming", "medium", "What is printed?", "from functools import lru_cache\n@lru_cache(None)\ndef fib(n):\n    return n if n < 2 else fib(n - 1) + fib(n - 2)\n\nprint(fib(30), fib.cache_info().misses)", "832040 31", ["832040 1346269", "832040 30", "1346269 31"], "Memoisation computes each of fib(0..30) once: 31 misses, versus about 2.7 million calls without the cache."),
        M("time-complexity", "easy", "What is the time complexity of this code?", "O(n^2)", ["O(n)", "O(log n)", "O(2^n)"], "Two nested loops of n iterations each execute the body n * n times.", fmt="complexity", code="for i in range(n):\n    for j in range(n):\n        total += i * j"),
        M("time-complexity", "medium", "What is the time complexity of this loop?", "O(log n)", ["O(n)", "O(n log n)", "O(sqrt n)"], "The variable doubles each iteration, so it takes about log2(n) steps to reach n.", fmt="complexity", code="i = 1\nwhile i < n:\n    i *= 2"),
        M("space-complexity", "medium", "What is the extra (auxiliary) space of this function?", "O(n): the result list holds n items", ["O(1)", "O(log n)", "O(n^2)"], "It builds a new list proportional to the input; the loop variables are constant.", fmt="complexity", code="def doubled(a):\n    return [x * 2 for x in a]"),
        M("space-complexity", "hard", "A recursive function f(n) calls f(n - 1) and does O(1) other work. What is its space complexity?", "O(n) because of the call stack", ["O(1)", "O(log n)", "O(2^n)"], "Each pending call occupies a stack frame; Python also limits depth (about 1000 by default).", fmt="complexity"),
        M("big-o", "easy", "Which describes Big O notation?", "An upper bound on growth rate as input size grows, ignoring constants", ["The exact running time in seconds", "The memory address of a function", "The best case only"], "O(2n + 5) simplifies to O(n); it describes scaling, not wall-clock time.", fmt="complexity"),
        M("big-o", "medium", "Order these from slowest-growing to fastest-growing: O(n^2), O(log n), O(n), O(n log n).", "O(log n), O(n), O(n log n), O(n^2)", ["O(n), O(log n), O(n^2), O(n log n)", "O(log n), O(n log n), O(n), O(n^2)", "O(n^2), O(n log n), O(n), O(log n)"], "Logarithmic < linear < linearithmic < quadratic.", fmt="complexity"),
        M("data-structure-choice", "medium", "You need fast membership tests and no duplicates for 1 million IDs. Which structure?", "set", ["list", "tuple", "str"], "A set gives average O(1) membership and enforces uniqueness."),
        M("data-structure-choice", "medium", "You need the 3 smallest values repeatedly from a changing collection. Which is most suitable?", "A heap (heapq): O(log n) push and O(k log n) to take k smallest", ["Sorting the list after every insert", "A set", "A string"], "heapq maintains the smallest element at index 0 efficiently; heapq.nsmallest also exists."),
        O("edge-cases", "medium", "What is printed?", "def avg(a):\n    return sum(a) / len(a)\n\ntry:\n    avg([])\nexcept ZeroDivisionError:\n    print('empty')", "empty", ["0", "nan", "None"], "An empty list makes len(a) zero; production code should decide on a defined result or raise a clear error."),
        M("edge-cases", "medium", "Which edge cases should you test for a function that returns the maximum of a list?", "Empty list, one element, duplicates, negatives and very large values", ["Only a list of positive numbers", "Only the example in the statement", "Only sorted input"], "Boundary and degenerate inputs find most bugs; decide the empty-list behaviour up front."),
    ]
